import React, { useState, useEffect } from 'react';
import { useOutletContext } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';
import './Security.css'; 

const SecurityPage = () => {
  const context = useOutletContext();
  const resumeData = Array.isArray(context) ? context[0] : context?.resumeData;
  const setResumeData = Array.isArray(context) ? context[1] : context?.setResumeData;

  const [scanType, setScanType] = useState('static');
  const [targetUrl, setTargetUrl] = useState('');
  const [scanResults, setScanResults] = useState(null);
  const [scanning, setScanning] = useState(false);

  // Sync state if it already exists globally
  useEffect(() => {
    if (resumeData && !Array.isArray(resumeData)) {
      setScanResults(resumeData);
    }
  }, [resumeData]);

  const runSecurityScan = async () => {
    setScanning(true);
    setScanResults(null);
    try {
      const response = await fetch('http://localhost:8000/api/security/scan', {
        method: 'POST',
        mode: 'cors',
        headers: { 
          'Content-Type': 'application/json' 
        },
        body: JSON.stringify({ 
          type: scanType, 
          url: targetUrl || "N/A"
        }),
      });
      
      if (!response.ok) throw new Error(`Server responded with ${response.status}`);
      
      const data = await response.json();
      
      // Update local view
      setScanResults(data);
      
      // CRITICAL HANDSHAKE: Push security scan telemetry to global tree
      if (setResumeData) {
        setResumeData(data);
      }
    } catch (error) {
      console.error("Scan failed:", error);
      alert("Scan failed. Check if FastAPI is running on port 8000.");
    } finally {
      setScanning(false);
    }
  };

  return (
    <div className="soc-container">
      <ProjectNavbar basePath="sec" links={["Threats", "Logs", "Integrity", "VPC"]} />
      
      <header className="soc-header">
        <h2>Security Operations Center (SOC)</h2>
        <div className="toggle-group" style={{ display: 'flex', gap: '10px' }}>
          <button 
            onClick={() => setScanType('static')} 
            className={`workspace-button ${scanType === 'static' ? 'active-tab' : 'inactive-tab'}`}
          >
            Static Scan
          </button>
          <button 
            onClick={() => setScanType('dynamic')} 
            className={`workspace-button ${scanType === 'dynamic' ? 'active-tab' : 'inactive-tab'}`}
          >
            External Scan
          </button>
        </div>
      </header>

      <div className="input-section">
        {scanType === 'dynamic' && (
          <input 
            type="text"
            className="workspace-textarea"
            placeholder="https://target-url.com"
            value={targetUrl}
            onChange={(e) => setTargetUrl(e.target.value)}
          />
        )}
        <button className="workspace-button soc-scan-btn" onClick={runSecurityScan} disabled={scanning}>
          {scanning ? 'Analyzing...' : 'Initiate Scan'}
        </button>
      </div>

      <div className="telemetry-log">
        <p>{'>'} System: {scanType.toUpperCase()} mode active.</p>
        {scanResults && <p style={{ color: '#22c55e' }}>{'>'} Scan Complete.</p>}
      </div>

      {scanResults && (
        <div className="summary-box">
          <pre>{JSON.stringify(scanResults, null, 2)}</pre>
        </div>
      )}
    </div>
  );
};

export default SecurityPage;
